const groups={carry:['パスポート','スマートフォン・充電に必要なもの','しおり','現金・貴重品','常備薬','モバイルバッテリー（手元に保管）'],luggage:['衣類・寝間着','洗面用具・歯ブラシ','衛生用品','帽子・雨具','充電器']};let checks={};try{checks=JSON.parse(localStorage.getItem('taiwan-packing-2026')||'{}')}catch{}for(const [group,items] of Object.entries(groups)){const root=document.getElementById(group);items.forEach((item,i)=>{const id=group+'-'+i;const label=document.createElement('label'),input=document.createElement('input'),text=document.createElement('span');input.type='checkbox';input.checked=checks[id]===true;text.textContent=item;input.addEventListener('change',()=>{checks[id]=input.checked;try{localStorage.setItem('taiwan-packing-2026',JSON.stringify(checks))}catch{}});label.append(input,text);root.append(label)})}